// 🔴 2026-09-26（InkStoneCo#17 comment 11577）：不帶參數觸發時 Gitea 404 的根因。
// graph-executor.ts interpolateString() 對「整段就是單一 {{x}} 引用」且 x 解不出來
// （trigger body 沒帶這個 key）時，回的是**字面字串** "{{input.org}}"，不是 undefined
// 也不是空字串（`return val === undefined ? s : val` 那個 s 就是原樣模板文字）。
// 舊寫法 `input.org == null ? '' : input.org` 把這個非 null 的字面字串當成「使用者填了值」，
// trim() 後仍是非空字串 ⇒ `|| 'inkstone'` 的預設值永遠不會生效 ⇒ org 變成
// 字面 "{{input.org}}" 這串垃圾，被塞進下面的 `/orgs/{{prep.data.org}}/repos` 路徑，
// Gitea 對不上任何 route 回 404（指向 /api/swagger 的那個泛用 404）。
// 修法：先過濾掉「整段還是沒解開的模板佔位符」這個狀態，再套預設值。
function unresolved(v) { return typeof v === 'string' && /^\{\{.*\}\}$/.test(v); }
var orgRaw = (input.org == null || unresolved(input.org)) ? '' : input.org;
var org = String(orgRaw).trim() || 'inkstone';
var fullRaw = (input.full == null || unresolved(input.full)) ? '0' : input.full;
var full = String(fullRaw) === '1';
// <ahub-auth login="global-index">
// 這支工作流對 AHub 的署名（身分＝global-index）。token＝'ahubapp_' + sha256('global-index:' + 實例 namespace)，只在執行當下算，
// 不存、不寫進定義；AHub 只存它的雜湊。回 null＝拿不到實例 namespace（模板沒解開）。
function appAuth(tenant) {
  var t = String(tenant == null ? '' : tenant).trim();
  if (!t || /^\{\{[^{}]*\}\}$/.test(t)) return null;
  var tok = 'ahubapp_' + sha256('global-index:' + t);
  return { login: 'global-index', tok: tok, hash: sha256(tok) };
}
// </ahub-auth>
var au = appAuth(input.tenant);
if (!au) throw new Error('找不到這台實例的 namespace（總圖要用它推出對 AHub 的署名）');
return { success: true, org: org, full: full ? 1 : 0, tok: au.tok, tokhash: au.hash };

// <ahub-unwrap>
// AHub 的信封 → Gitea 形狀。非 2xx 時把原因帶出來，不假裝是空陣列。
function ahubBody(v) {
  if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return { err: 'AHub 沒有回 JSON' }; } }
  var d = v && v.data && typeof v.data === 'object' ? v.data : null;
  if (d && d.data && typeof d.data === 'object' && typeof d.data.status === 'number') d = d.data;
  if (!d || typeof d.status !== 'number') return { err: 'AHub 沒有回 {status, body}（工作流壞了、或 AHub App 沒裝）' };
  if (d.status < 200 || d.status >= 300) return { err: 'AHub 回 ' + d.status + '：' + String((d.body && d.body.message) || '').slice(0, 120), status: d.status };
  return { body: d.body, status: d.status };
}
// </ahub-unwrap>
var u = ahubBody(input.repos_raw);
// 讀不到 repo 清單 = 後面整條都沒有意義：用 throw 讓這次執行記成失敗（return success:false 在 code 節點只是一個值，流程會照常往下走）
if (u.err) throw new Error('AHub /orgs/' + input.org + '/repos：' + u.err);
var raw = u.body;
if (!Array.isArray(raw)) throw new Error('AHub /orgs/' + input.org + '/repos 沒有回一個 repo 陣列（拿到 ' + (typeof raw) + '）');
var repos = raw.map(function (r) {
  return { name: String(r.name || ''), archived: !!r.archived };
}).filter(function (r) { return r.name; });
var PAGES = 3;   // 3 頁 × 100 張 = AHub issue_search 的掃描上限 300
var pages = [];
for (var i = 1; i <= PAGES; i++) pages.push({ n: i });
return { success: true, org: input.org, repos: repos, repo_count: repos.length, scan_cap: PAGES * 100, page_count: PAGES, pages: pages };

// <ahub-unwrap>
// AHub 的信封 → Gitea 形狀。非 2xx 時把原因帶出來，不假裝是空陣列。
function ahubBody(v) {
  if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return { err: 'AHub 沒有回 JSON' }; } }
  var d = v && v.data && typeof v.data === 'object' ? v.data : null;
  if (d && d.data && typeof d.data === 'object' && typeof d.data.status === 'number') d = d.data;
  if (!d || typeof d.status !== 'number') return { err: 'AHub 沒有回 {status, body}（工作流壞了、或 AHub App 沒裝）' };
  if (d.status < 200 || d.status >= 300) return { err: 'AHub 回 ' + d.status + '：' + String((d.body && d.body.message) || '').slice(0, 120), status: d.status };
  return { body: d.body, status: d.status };
}
// </ahub-unwrap>
function one(s) { return String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); }
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
var org = String(input.org || 'inkstone');
var full = String(input.full) === '1';
var repos = Array.isArray(input.repos) ? input.repos : [];
var scanCap = Number(input.scan_cap) || 0;

// 票：把每一頁的結果攤平；一頁壞掉就記下來，不假裝那頁是空的
var pageResults = Array.isArray(input.pages) ? input.pages : [];
var rows = [];
var badPages = 0;
var badWhy = '';
pageResults.forEach(function (r) {
  var u = r && r.success !== false ? ahubBody(r) : { err: '這一頁的請求沒成功' };
  var arr = u.err ? null : u.body;
  if (!Array.isArray(arr)) { badPages++; badWhy = badWhy || u.err || '回的不是票陣列'; return; }
  arr.forEach(function (i) {
    if (!i || i.pull_request) return;
    var repo = (i.repository && i.repository.name) || '?';
    var labs = (i.labels || []).map(function (l) { return l.name; });
    rows.push({ repo: repo, n: i.number, t: i.title, l: labs, m: i.milestone ? i.milestone.title : '', c: i.created_at, u: i.updated_at });
  });
});
if (rows.length === 0) { return { success: false, error: '票 index 一張票都算不出來（' + pageResults.length + ' 頁、' + badPages + ' 頁壞' + (badWhy ? '：' + badWhy : '') + '）→ 不注入（寧可冷啟動，不要注入垃圾）' }; }
// 每個 repo 的 open 票數：AHub 的 repo 沒有票數欄，由抓回來的票現算
var openBy = {};
rows.forEach(function (r) { openBy[r.repo] = (openBy[r.repo] || 0) + 1; });
repos.forEach(function (r) { r.open = openBy[r.name] || 0; });
Object.keys(openBy).forEach(function (k) { if (!repos.some(function (r) { return r.name === k; })) repos.push({ name: k, archived: false, open: openBy[k] }); });

// 知識：藏書地圖
var libs = null;
try { var m = parse(input.map_body); if (m && Array.isArray(m.libraries)) libs = m.libraries; } catch (e) { libs = null; }

var ACT = { 's/doing': 1, 's/stage': 1, 's/triage': 1 };
var NEXT = { 's/todo': 1 };
function stateOf(r) {
  var s = r.l.filter(function (x) { return x.indexOf('s/') === 0; });
  if (s.length === 0) return 'unlabeled';
  for (var i = 0; i < s.length; i++) { if (ACT[s[i]]) return 'active'; }
  for (var j = 0; j < s.length; j++) { if (NEXT[s[j]]) return 'next'; }
  return 'later';
}
function rank(r) {
  var a = r.l.indexOf('s/doing') >= 0 ? 0 : (r.l.indexOf('s/stage') >= 0 ? 1 : 2);
  var b = r.l.indexOf('p/high') >= 0 ? 0 : 1;
  return a * 10 + b;
}
function byRepo(list) {
  var g = {};
  list.forEach(function (r) { (g[r.repo] = g[r.repo] || []).push(r); });
  return g;
}
var act = [], next = [], later = [], unl = [];
rows.forEach(function (r) {
  var st = stateOf(r);
  if (st === 'active') act.push(r); else if (st === 'next') next.push(r); else if (st === 'unlabeled') unl.push(r); else later.push(r);
});
act.sort(function (x, y) { return (rank(x) - rank(y)) || (x.repo < y.repo ? -1 : x.repo > y.repo ? 1 : 0) || (x.n - y.n); });

var NOW = Date.now();
var DAY = 24 * 60 * 60 * 1000;
function ms(s) { var t = Date.parse(s || ''); return isNaN(t) ? 0 : t; }
var fresh = rows.filter(function (r) { return ms(r.c) > NOW - DAY || ms(r.u) > NOW - DAY; });
fresh.sort(function (x, y) { return (ms(y.u) || ms(y.c)) - (ms(x.u) || ms(x.c)); });

var L = [];
L.push('# 全局總圖：現在有哪些票、庫裡有哪些知識');
L.push('（雲端現算 ' + new Date().toISOString() + '　·　真相源＝AHub `' + org + '/*`，這份是投影，改它沒用，下次開場會重算）');
L.push('');
if (fresh.length) {
  L.push('## 🆕 過去 24 小時有 ' + fresh.length + ' 張票動過——**規劃前先看這段**');
  fresh.slice(0, 12).forEach(function (r) {
    var isNew = ms(r.c) > NOW - DAY;
    L.push('- ' + (isNew ? '**新開** ' : '變動 ') + '`' + org + '/' + r.repo + '#' + r.n + '` — ' + one(r.t));
  });
  if (fresh.length > 12) { L.push('- …還有 ' + (fresh.length - 12) + ' 張（按最後變動時間排，上面是最近的）'); }
  L.push('');
}

// 一、票：先講每個 repo 有幾張（leo：「你不知道哪個 repo 有哪些票」——這一行就是解那句的）
var withIssues = repos.filter(function (r) { return r.open > 0; }).sort(function (a, b) { return b.open - a.open || (a.name < b.name ? -1 : 1); });
var zero = repos.filter(function (r) { return r.open === 0; }).map(function (r) { return r.name; });
L.push('## 一、票 — AHub `' + org + '` ' + repos.length + ' 個 repo，' + withIssues.length + ' 個有票，開著 ' + rows.length + ' 張');
L.push('');
L.push('### 每個 repo 的 open 票數');
withIssues.forEach(function (r) { L.push('- `' + org + '/' + r.name + '` ' + r.open + ' 張'); });
if (zero.length) L.push('- 0 張：' + zero.map(function (n) { return '`' + n + '`'; }).join(' '));
if (badPages > 0) {
  L.push('');
  L.push('> ⚠️ ' + pageResults.length + ' 頁裡有 ' + badPages + ' 頁沒抓成（' + badWhy + '）——上面的清單**不完整**，缺的那些去 AHub 補查。');
}
if (scanCap && rows.length >= scanCap) {
  L.push('');
  L.push('> ⚠️ AHub 的跨 repo 搜尋一次只掃最近 ' + scanCap + ' 張開著的票，這次剛好抓滿 ' + rows.length + ' 張——**可能還有更舊的票沒列進來**。要確認某個 repo 的全部，直接打該 repo 的 `issues`。');
}
L.push('');
L.push('### 在做的（' + act.length + ' 張；s/doing · s/stage · s/triage）');
act.forEach(function (r) {
  L.push('- `' + org + '/' + r.repo + '#' + r.n + '` ' + r.l.join(' ') + ' — ' + one(r.t) + (r.m ? '　〔' + one(r.m) + '〕' : ''));
});
L.push('');
function numbersLine(title, list) {
  var g = byRepo(list);
  L.push('### ' + title + '（' + list.length + ' 張' + (full ? '' : '；只給編號，要看內容自己去 AHub，或 `full=1` 重跑') + '）');
  Object.keys(g).sort().forEach(function (k) {
    if (full) { g[k].forEach(function (r) { L.push('- `' + org + '/' + k + '#' + r.n + '` ' + r.l.join(' ') + ' — ' + one(r.t)); }); }
    else { L.push('- **' + k + '**：' + g[k].map(function (r) { return '#' + r.n; }).join(' ')); }
  });
  L.push('');
}
numbersLine('排好等開工的（s/todo）', next);
if (unl.length) numbersLine('沒標狀態的（沒有 s/* 標籤——先驗傷再決定）', unl);
numbersLine('現在不該挑來做的（s/backlog · s/review · s/pending 等）', later);
L.push('> 上面沒有「誰擋誰」：擋路關係只能一張一張問，會把每次執行 50 個外部請求的額度吃光。');
L.push('> ⇒ **挑票開工前，自己打一次那張票的 `/dependencies` 確認前置做完了沒。**');
L.push('');

// 二、知識
L.push('## 二、知識 — KBDB 藏書地圖');
if (libs === null) {
  L.push('⚠️ 這次取不到藏書地圖，這一半**不注入**（寧可冷啟動，不要注入垃圾）。要查請直接打 `kbdb_get_map()`。');
} else {
  L.push('一庫一行，只說「有哪些庫、各裝了什麼」。三步走：`kbdb_get_map` → `kbdb_get_index(library)` → `kbdb_get_card`。');
  libs.forEach(function (x) {
    var top = (x.top_entities || []).slice(0, 3).join(' / ');
    var ec = typeof x.entry_count === 'number' ? x.entry_count + ' 筆內容' : '';
    if (x.triplet_count > 0 || x.entry_count > 0) {
      L.push('- `' + x.library + '` — ' + [ec, (x.triplet_count || 0) + ' 條三元組'].filter(Boolean).join('、') + (top ? '；核心：' + top : '') + (x.narrative ? '；' + one(x.narrative).slice(0, 80) : ''));
    } else {
      L.push('- `' + x.library + '` — **空的**');
    }
  });
}
L.push('');
L.push('---');
L.push('- **票不可以用舊的**：以上是這一刻的狀態。要動某一張之前先單獨重查那一張——你吃個飯回來它就可能被改了。');
L.push('- **知識可以稍舊**：庫裡的內容昨天寫的今天讀還是對的。');
L.push('- **這是 index 不是內容**：它只讓你知道「有這件事、去哪裡找」，細節在票上與庫裡。');

var md = L.join('\n');
return { success: true, md: md, bytes: md.length, org: org, repo_count: repos.length, repos_with_issues: withIssues.length, open_issues: rows.length, scan_cap: scanCap, pages: pageResults.length, bad_pages: badPages, active: act.length, libraries: libs === null ? 0 : libs.length };
